import React from 'react'
import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';


const TakeQuiz = () => {

        const location = useLocation();
        const { state: formData } = location;

        const [loading, setLoading] = useState(false);
        const [error, setError] = useState(null); 
        const [quizData, setQuizData] = useState(null); 

        const prompt = `Generate a set of quiz questions having 4 choices and 1 correct answer based on the following data given in JSON format : 

        ${JSON.stringify(formData)} 

        Generate the questions in json format.`

        const fetchQuiz = async () => {
                console.log("Loading...");
                setLoading(true);
                try{
                        const response = await axios ({
                                url:"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=AIzaSyDzzLAYxe6PJiBrh_dL5B020aO6pIZx6NQ",
                                method:"post",
                                data:{
                                        contents:[{parts : [{text:prompt}]}],
                                },
                        });
                        console.log("Response : ", response);

                        if (response.data && response.data.candidates.length > 0) {
                                // Extract the generated quiz text from the response
                                const content = response.data.candidates[0]?.content?.parts[0]?.text;
                                setQuizData(content);

                        }

                        else {
                                setError("No valid content returned from the API");
                        }

                } catch (err){
                        console.error("Error fetching quiz:", err);
                        setError("An error occurred while fetching the quiz questions.");
                }
                finally {
                        setLoading(false);
                }



        }

        useEffect(() => {
                if (formData){
                        fetchQuiz();
                }
        },[formData])


        function stringToJson(inputString) {
                try {
                    const json = JSON.parse(inputString.trim());
                    return json;
                } catch (error) {
                    console.error("Invalid JSON string. Please check the input format.", error);
                    return null;
                }
        }

        const quiz = stringToJson(quizData);



        return (
                <div className="container mx-auto p-4">

                        {loading && <p className="text-center text-blue-600">Loading...</p>}
                        {error && <p className="text-center text-red-600" style={{ color: "red" }}>{error}</p>}
                        {quizData && (
                                <div>
                                        <h3 className="text-xl font-semibold text-center mb-4">Quiz Questions</h3>
                                        <pre className="bg-gray-100 p-4 rounded-lg shadow-lg max-h-[400px] overflow-auto text-sm font-mono whitespace-pre-wrap break-words">{quizData}</pre>
                                </div>
                        )}

                </div>
        )

}

export default TakeQuiz
